package e.e.a;
import android.app.*;import android.content.*;import android.preference.PreferenceManager;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;
/** Date boundaries are inclusive dates in Japan; durations are seconds. */
public final class SearchRange {
 static final String PREFIX="search_range_";static SharedPreferences settings;
 static Calendar day(long millis){Calendar c=Calendar.getInstance(TimeZone.getTimeZone("Asia/Tokyo"));c.setTimeInMillis(millis);c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);return c;}
 static long[] preset(int mode,long now){Calendar first=day(now);long end=first.getTimeInMillis();if(mode==1)first.add(Calendar.DAY_OF_MONTH,-7);else if(mode==2)first.add(Calendar.MONTH,-1);else if(mode==3)first.add(Calendar.YEAR,-1);return new long[]{first.getTimeInMillis(),end};}
 static long[] initialDates(int selected,long from,long to,long now){return selected==8&&from<=to?new long[]{day(from).getTimeInMillis(),day(to).getTimeInMillis()}:preset(0,now);}
 static String date(long n){SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd",Locale.ROOT);f.setTimeZone(TimeZone.getTimeZone("Asia/Tokyo"));return f.format(new Date(n));}
 static String stamp(long n){SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ssXXX",Locale.ROOT);f.setTimeZone(TimeZone.getTimeZone("Asia/Tokyo"));return f.format(new Date(n));}
 static Button rangeButton(Context c,String title){Button b=PanelUi.button(c,title);UiDialogs.secondaryButton(b);return b;}
 static ScrollView scrolled(LinearLayout b){ScrollView s=new ScrollView(b.getContext());s.addView(b,new ViewGroup.LayoutParams(-1,-2));return s;}
 static String title(int[] values,int slot){return label(values,slot);}
 static LinearLayout box(Context c){LinearLayout b=PanelUi.column(c);int n=PanelUi.dp(c,16);b.setPadding(n,n,n,n);return b;}
 static Button button(LinearLayout b,String title,Runnable action){Button v=rangeButton(b.getContext(),title);v.setOnClickListener(w->action.run());b.addView(v);return v;}
 public static void alignInput(View view){if(!(view instanceof AutoCompleteTextView)||!(view.getParent() instanceof RelativeLayout))return;RelativeLayout row=(RelativeLayout)view.getParent();ImageButton history=null;for(int i=0;i<row.getChildCount();i++)if(row.getChildAt(i) instanceof ImageButton)history=(ImageButton)row.getChildAt(i);if(history==null)return;int inset=PanelUi.dp(view.getContext(),16);row.setPadding(row.getPaddingLeft(),Math.max(row.getPaddingTop(),inset),row.getPaddingRight(),row.getPaddingBottom());for(View child:new View[]{view,history}){RelativeLayout.LayoutParams p=(RelativeLayout.LayoutParams)child.getLayoutParams();p.topMargin=0;p.bottomMargin=0;p.height=PanelUi.dp(view.getContext(),50);p.addRule(RelativeLayout.CENTER_VERTICAL);child.setLayoutParams(p);}EditText field=(EditText)view;field.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);field.setIncludeFontPadding(false);int pad=PanelUi.dp(view.getContext(),8);field.setPadding(field.getPaddingLeft(),pad,field.getPaddingRight(),pad);history.setScaleType(ImageView.ScaleType.CENTER_INSIDE);}
 static void install(Context c,View root,int[] values){settings=PreferenceManager.getDefaultSharedPreferences(c);replace(c,root,0x7f080189,values,2);replace(c,root,0x7f08018a,values,3);}
 static void replace(Context c,View root,int id,int[] values,int slot){View old=root.findViewById(id);if(old==null||!(old.getParent() instanceof ViewGroup))return;if(old instanceof Spinner)((Spinner)old).setOnItemSelectedListener(null);ViewGroup parent=(ViewGroup)old.getParent();Button button=rangeButton(c,"");button.setTag("nicoid-range-control");button.setBackgroundTintList(null);button.setBackgroundColor(android.graphics.Color.TRANSPARENT);button.setElevation(0);button.setGravity(Gravity.START|Gravity.TOP);button.setIncludeFontPadding(false);button.setPadding(PanelUi.dp(c,12),PanelUi.dp(c,12),PanelUi.dp(c,12),PanelUi.dp(c,8));button.setMinHeight(0);button.setMinimumHeight(PanelUi.dp(c,56));button.setSingleLine(false);button.setMaxLines(3);render(c,values,slot,button);ViewGroup.LayoutParams layout=old.getLayoutParams();if(parent instanceof LinearLayout){LinearLayout row=(LinearLayout)parent;row.setOrientation(LinearLayout.HORIZONTAL);row.setWeightSum(2f);row.setPadding(0,0,0,0);row.setGravity(Gravity.CENTER_VERTICAL);row.setBackground(PanelUi.round(c,DialogColors.secondary(UiDialogs.surface(c),ThemeChoice.isNight(c)),10));if(row.getLayoutParams()!=null){ViewGroup.LayoutParams p=row.getLayoutParams();p.height=ViewGroup.LayoutParams.WRAP_CONTENT;row.setLayoutParams(p);}layout=new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1);}else layout.height=ViewGroup.LayoutParams.WRAP_CONTENT;int index=parent.indexOfChild(old);old.setVisibility(View.GONE);parent.addView(button,index,layout);if(slot==3&&parent instanceof LinearLayout){View divider=new View(c);divider.setBackgroundColor((PanelUi.ink(c)&0xffffff)|0x22000000);parent.addView(divider,parent.indexOfChild(button),new LinearLayout.LayoutParams(PanelUi.dp(c,1),PanelUi.dp(c,36)));}button.setOnClickListener(v->{if(slot==2)dates(c,values,button);else durations(c,values,button);});}
 static void render(Context c,int[] values,int slot,Button button){String heading=PanelUi.tr(c,slot==2?"投稿期間":"時間",slot==2?"Posted":"Duration",slot==2?"投稿期間":"時間");String summary=tr(label(values,slot));if(slot==2&&values[2]==8)summary=summary.replace(" ～ ","\n～ ");android.text.SpannableString text=new android.text.SpannableString(heading+"\n"+summary);text.setSpan(new android.text.style.ForegroundColorSpan(DialogColors.muted(ThemeChoice.isNight(c))),0,heading.length(),33);text.setSpan(new android.text.style.AbsoluteSizeSpan(12,true),0,heading.length(),33);text.setSpan(new android.text.style.AbsoluteSizeSpan(15,true),heading.length()+1,text.length(),33);button.setText(text);}
 static String tr(String text){return UiStrings.translate(text);}
 static String label(int[] values,int slot){if(values[slot]!=8)return slot==2?SearchFilters.PERIOD[Math.max(0,Math.min(7,values[slot]))]:SearchFilters.LENGTH[Math.max(0,Math.min(7,values[slot]))];if(slot==2)return date(settings.getLong(PREFIX+"from",System.currentTimeMillis()))+" ～ "+date(settings.getLong(PREFIX+"to",System.currentTimeMillis()));int min=settings.getInt(PREFIX+"min",0),max=settings.getInt(PREFIX+"max",0);return time(min)+" ～ "+(max==0?"上限なし":time(max));}
 static String time(int s){return String.format(Locale.ROOT,"%d:%02d",s/60,s%60);}
 static void picker(Context c,long value,java.util.function.LongConsumer out){Calendar day=day(value);DatePickerDialog d=new DatePickerDialog(UiTheme191.context(c),(v,y,m,n)->{Calendar selected=day(value);selected.set(y,m,n);out.accept(selected.getTimeInMillis());},day.get(Calendar.YEAR),day.get(Calendar.MONTH),day.get(Calendar.DAY_OF_MONTH));d.show();UiDialogs.style(d);}
 static void dates(Context c,int[] values,Button anchor){LinearLayout b=box(c);long now=day(System.currentTimeMillis()).getTimeInMillis();long[] range=initialDates(values[2],settings.getLong(PREFIX+"from",now),settings.getLong(PREFIX+"to",now),now);int[] mode={values[2]==8?settings.getInt(PREFIX+"mode",0):0};Button[] start={null},end={null};Runnable refresh=()->{start[0].setText("開始日："+date(range[0]));end[0].setText("終了日："+date(range[1]));};String[] names={"日","週","月","年"};LinearLayout modes=new LinearLayout(c);b.addView(modes);for(int i=0;i<4;i++){final int n=i;Button v=rangeButton(c,names[i]);modes.addView(v,new LinearLayout.LayoutParams(0,-2,1));v.setOnClickListener(w->{mode[0]=n;long[] current=preset(n,System.currentTimeMillis());range[0]=current[0];range[1]=current[1];refresh.run();});}
 start[0]=button(b,"",()->picker(c,range[0],n->{range[0]=n;if(range[1]<n)range[1]=n;refresh.run();}));end[0]=button(b,"",()->picker(c,range[1],n->{range[1]=n;if(range[0]>n)range[0]=n;refresh.run();}));LinearLayout arrows=new LinearLayout(c);b.addView(arrows);for(int side:new int[]{-1,1}){Button v=rangeButton(c,side<0?"◀ 前の期間":"次の期間 ▶");arrows.addView(v,new LinearLayout.LayoutParams(0,-2,1));v.setOnClickListener(w->{Calendar d=day(range[0]);int unit=mode[0]==0?Calendar.DAY_OF_MONTH:mode[0]==1?Calendar.WEEK_OF_YEAR:mode[0]==2?Calendar.MONTH:Calendar.YEAR;d.add(unit,side);range[0]=d.getTimeInMillis();Calendar endDate=day(range[1]);endDate.add(unit,side);range[1]=endDate.getTimeInMillis();refresh.run();});}refresh.run();AlertDialog d=UiDialogs.builder(c).setTitle("投稿日の範囲").setView(scrolled(b)).setPositiveButton("適用",(x,w)->{settings.edit().putLong(PREFIX+"from",range[0]).putLong(PREFIX+"to",range[1]).putInt(PREFIX+"mode",mode[0]).apply();values[2]=8;render(c,values,2,anchor);}).setNeutralButton("指定なし",(x,w)->{values[2]=0;render(c,values,2,anchor);}).setNegativeButton("キャンセル",null).create();UiDialogs.show(d);}
 static void durations(Context c,int[] values,Button anchor){
  LinearLayout b=box(c);int initialMin=values[3]==8?settings.getInt(PREFIX+"min",0):SearchFilterRules.min(values[3]),initialMax=values[3]==8?settings.getInt(PREFIX+"max",0):SearchFilterRules.max(values[3]);
  DurationRangeModel model=new DurationRangeModel(initialMin,initialMax==0?Math.max(900,initialMin):initialMax,initialMax==0);
  EditText low=new EditText(c),high=new EditText(c);low.setSingleLine(true);high.setSingleLine(true);low.setHint("最短（分:秒）");high.setHint("最長（分:秒）");low.setText(time(model.low));high.setText(time(model.high));b.addView(low);b.addView(high);
  CheckBox unlimited=new CheckBox(c);unlimited.setText("上限なし");unlimited.setChecked(model.unlimited);b.addView(unlimited);TextView rangeLabel=PanelUi.text(c,"",16);b.addView(rangeLabel);
  DurationRangeBar bar=new DurationRangeBar(c,Math.max(7200,model.high));boolean[] syncing={false};
  Runnable draw=()->{bar.low=model.low;bar.high=model.high;bar.unlimited=model.unlimited;bar.max=Math.max(7200,Math.max(model.low,model.high));bar.invalidate();high.setEnabled(!model.unlimited);rangeLabel.setText(time(model.low)+" ～ "+(model.unlimited?"上限なし":time(model.high)));};
  Runnable fields=()->{syncing[0]=true;low.setError(null);high.setError(null);low.setText(time(model.low));high.setText(time(model.high));unlimited.setChecked(model.unlimited);syncing[0]=false;draw.run();};
  android.text.TextWatcher typed=new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){}public void afterTextChanged(android.text.Editable text){if(syncing[0])return;try{model.typed(parse(low.getText().toString()),model.unlimited?model.high:parse(high.getText().toString()));low.setError(null);high.setError(null);bar.setEnabled(true);draw.run();}catch(IllegalArgumentException error){bar.setEnabled(false);rangeLabel.setText("分:秒で、最短 ≦ 最長になるよう指定してください");}}};
  low.addTextChangedListener(typed);high.addTextChangedListener(typed);
  unlimited.setOnCheckedChangeListener((v,checked)->{if(syncing[0])return;model.unlimited=checked;try{model.typed(parse(low.getText().toString()),Math.max(parse(low.getText().toString()),checked?model.high:parse(high.getText().toString())));bar.setEnabled(true);fields.run();}catch(IllegalArgumentException error){bar.setEnabled(false);}});
  bar.changed=(min,max)->{model.dragged(min,max);fields.run();};b.addView(bar,new LinearLayout.LayoutParams(-1,PanelUi.dp(c,64)));
  String[] presets={"1分以内","1～5分","5～10分","10分以上"};int[][] bounds={{0,60},{60,300},{300,600},{600,900}};LinearLayout quick=new LinearLayout(c);b.addView(quick);
  for(int i=0;i<4;i++){final int n=i;Button v=rangeButton(c,presets[i]);quick.addView(v,new LinearLayout.LayoutParams(0,-2,1));v.setOnClickListener(w->{model.low=bounds[n][0];model.high=bounds[n][1];model.unlimited=n==3;bar.setEnabled(true);fields.run();});}
  draw.run();AlertDialog d=UiDialogs.builder(c).setTitle("動画時間の範囲").setView(scrolled(b)).setPositiveButton("適用",null).setNeutralButton("指定なし",(x,w)->{values[3]=0;render(c,values,3,anchor);}).setNegativeButton("キャンセル",null).create();UiDialogs.show(d);
  d.getButton(-1).setOnClickListener(v->{try{model.unlimited=unlimited.isChecked();model.typed(parse(low.getText().toString()),model.unlimited?model.high:parse(high.getText().toString()));settings.edit().putInt(PREFIX+"min",model.low).putInt(PREFIX+"max",model.maximum()).apply();values[3]=8;render(c,values,3,anchor);d.dismiss();}catch(IllegalArgumentException error){low.setError("分:秒で、最短 ≦ 最長になるよう指定してください");}});
 }

 static int parse(String s){String[] p=s.trim().split(":",-1);if(p.length>2||p.length==0)throw new IllegalArgumentException();int m=Integer.parseInt(p[0]),sec=p.length==2?Integer.parseInt(p[1]):0;if(m<0||sec<0||sec>59||m>100000)throw new IllegalArgumentException();return m*60+sec;}
 static String url(int[] values,String keyword){String base=SearchFilterRules.url(values,keyword);if(settings==null&&CacheFolders.context!=null)settings=PreferenceManager.getDefaultSharedPreferences(CacheFolders.context);if(settings==null)return base;StringBuilder b=new StringBuilder(base);if(values[2]==8){long from=settings.getLong(PREFIX+"from",0),to=settings.getLong(PREFIX+"to",from);Calendar end=day(to);end.add(Calendar.DAY_OF_MONTH,1);b.append("&minRegisteredAt=").append(SearchFilterRules.encode(stamp(day(from).getTimeInMillis()))).append("&maxRegisteredAt=").append(SearchFilterRules.encode(stamp(end.getTimeInMillis()-1000)));}if(values[3]==8){int min=settings.getInt(PREFIX+"min",0),max=settings.getInt(PREFIX+"max",0);if(min>0)b.append("&minDuration=").append(min);if(max>0)b.append("&maxDuration=").append(max);}return b.toString();}
}
